"""In-app notifications generated by real application events.

De-duplication: every notification has a `dedup_key` naming the event (for
example "assignment:12:assigned" or "maturity:7:2026-12-31:15"). The database
enforces one row per (recipient, dedup_key), and inserts use ON CONFLICT DO
NOTHING, so repeating an event, a lifecycle check or a page load never creates
copies. Notification text never contains AICTE internal notes, screening
findings or another institution's details.
"""

from collections.abc import Iterable

from sqlalchemy import select
from sqlalchemy.dialects.sqlite import insert as sqlite_insert
from sqlalchemy.orm import Session

from app.db.base import utcnow
from app.models import User, UserRole
from app.models.lifecycle import Notification


def aicte_officials(db: Session) -> list[User]:
    return list(db.scalars(select(User).where(User.role == UserRole.AICTE_OFFICIAL, User.is_active.is_(True))).all())


def institution_users(db: Session, institution_id: int) -> list[User]:
    return list(db.scalars(
        select(User).where(User.institution_id == institution_id, User.is_active.is_(True))
    ).all())


def notify(
    db: Session,
    recipients: Iterable[User],
    *,
    event_type: str,
    title: str,
    body: str,
    dedup_key: str,
    link: str | None = None,
    fdr_id: int | None = None,
) -> int:
    """Queue notifications in the caller's transaction. Returns how many were newly created."""
    if link is not None and (not link.startswith("/") or link.startswith("//")):
        raise ValueError("Notification links must be in-app paths")
    created = 0
    now = utcnow()
    for recipient in {user.id: user for user in recipients}.values():
        statement = (
            sqlite_insert(Notification)
            .values(
                recipient_id=recipient.id, event_type=event_type, title=title[:200], body=body[:500],
                link=link, fdr_id=fdr_id, dedup_key=dedup_key[:200], created_at=now,
            )
            .on_conflict_do_nothing(index_elements=["recipient_id", "dedup_key"])
        )
        created += db.execute(statement).rowcount or 0
    return created
